/**
 * Cloud provider logomarks as PNG data URLs.
 *
 * brand asset not included in this repository: the original module (generated by scripts/gen-cloud-logos.cjs
 * from the providers' official SVGs) held colour PNG marks. Every key is kept with an empty
 * string, so the deck shows the provider name without a mark. Supply your own data URLs here, or
 * re-run the generator with the SVGs you are entitled to use.
 */
export const CLOUD_LOGOS = {
  AWS: '',
  Azure: '',
  GCP: '',
} as const;

export type CloudLogoKey = keyof typeof CLOUD_LOGOS;
